import subprocess, tempfile, os, struct
def run(*a, stdin=None):
    import subprocess as sp
    return sp.run(['./executable']+list(a), input=stdin, capture_output=True)
def idx_vals(path):
    data=open(path,"rb").read()
    n=len(data)//8
    return struct.unpack('>'+'Q'*n, data), data.hex()
with tempfile.TemporaryDirectory() as td:
    for content in [b'a,b\n"hello\nworld",2\n3,4\n', b'a,b\n1,2,3\n', b'a\n1\n2\n3\n4\n5\n']:
        f=os.path.join(td,"t.csv")
        open(f,"wb").write(content)
        p=run('index', f)
        if p.returncode!=0:
            print(content, "index failed", p.stderr)
        else:
            vals, hx = idx_vals(f+".idx")
            print(f"{content!r} => {vals}")
        try: os.remove(f)
        except: pass
        try: os.remove(f+".idx")
        except: pass
PY"}

