def csv_writer_to_buffer(rows, delimiter=",", quotechar='"', escapechar=None, quote_always=False, crlf=False, ascii_mode=False):
    # rows: list of lists
    # returns bytes
    out = io.StringIO(newline='')
    lineterm = '\r\n' if crlf and not ascii_mode else '\n'
    if ascii_mode:
        # field \x1f, record \x1e, no quoting? Actually ascii mode: uses those separators, no quoting?
        # Observed: fmt --ascii with a,b -> a\x1fb\x1e...
        # So delimiter is \x1f, lineterm \x1e, no quotes?
        # What about fields containing those? Probably no quoting.
        # We'll just join with \x1f and \x1e, no quoting.
        parts = []
        for row in rows:
            parts.append('\x1f'.join(row) + '\x1e')
        return (''.join(parts)).encode('utf-8')
    if escapechar is not None:
        # writer with escapechar, doublequote False
        w = csv.writer(out, delimiter=delimiter, quotechar=quotechar, escapechar=escapechar, doublequote=False, quoting=csv.QUOTE_ALL if quote_always else csv.QUOTE_MINIMAL, lineterminator=lineterm)
    else:
        w = csv.writer(out, delimiter=delimiter, quotechar=quotechar, doublequote=True, quoting=csv.QUOTE_ALL if quote_always else csv.QUOTE_MINIMAL, lineterminator=lineterm)
    for r in rows:
        if len(r) == 0:
            # original outputs '""\n' for zero columns? Let's check: select with empty gives '""\n'
            # csv writer with [] gives '\n' (just lineterm), not '""\n'. So need special.
            out.write('""' + lineterm)
        else:
            w.writerow(r)
    return out.getvalue().encode('utf-8')

def write_csv_output(rows, output_path, delimiter=",", quotechar='"', escapechar=None, quote_always=False, crlf=False, ascii_mode=False):
    data = csv_writer_to_buffer(rows, delimiter, quotechar, escapechar, quote_always, crlf, ascii_mode)
    if output_path is None:
        sys.stdout.buffer.write(data)
    else:
        try:
            # ensure parent exists? Original creates parent? No, fails if parent missing. So just open.
            with open(output_path, "wb") as f:
                f.write(data)
        except IsADirectoryError:
            write_stderr("Is a directory (os error 21)\n")
            sys.exit(1)
        except FileNotFoundError:
            write_stderr("No such file or directory (os error 2)\n")
            sys.exit(1)
        except OSError as e:
            write_stderr(str(e) + "\n")
            sys.exit(1)

